            "acceptance": [
              "相同幂等键重放只创建一条初始为 new 且归属调用者和调用者部门的线索。",
              "本人可更新规定字段并沿合法边推进状态，同部门非负责人写入被拒绝且状态不变。",
              "converted 和 lost 为不可变终态，所有变化有审计记录。"
            ]
          },
          "objects": {
            "lead": {
              "fields": {
                "company_name": "text!",
                "contact_name": "text",
                "contact_phone": "phone",
                "expected_amount": "currency!;precision=18;scale=2;rounding=half_even",
                "source": "select![website:官网|exhibition:展会|referral:转介绍|outbound:外呼]",
                "status": "select![new:新建|contacted:已跟进|qualified:合格|converted:已转化|lost:丢失]=new"
              },
              "lifecycle_policy": {
                "mode": "immutable_after_state",
                "state_field": "status",
                "immutable_states": [
                  "converted",
                  "lost"
                ]
              }
            },
            "lead_audit": {
              "fields": {
                "lead": "relation!->lead",
                "actor": "user!",
                "operation": "select![created|updated|contacted|qualified|converted|lost|approval_requested|approval_rejected]",
                "from_status": "select![new|contacted|qualified|converted|lost]",
                "to_status": "select![new|contacted|qualified|converted|lost]",
                "detail": "long_text",
                "occurred_at": "datetime!"
              },
              "lifecycle_policy": {
                "mode": "append_only"
              }
            }
          },
          "actions": {
            "lead.register": {
              "kind": "object_operation",
              "input": {
                "company_name": "text!",
                "contact_name": "text",
                "contact_phone": "phone",
                "expected_amount": "currency!;precision=18;scale=2;rounding=half_even",
                "source": "select![website:官网|exhibition:展会|referral:转介绍|outbound:外呼]"
              },
              "output": {
                "lead_id": "text!"
              },
              "handler": {
                "reason": "线索初始状态、可信负责人和部门归属及创建审计必须由同一原子命令派生。",
                "access": {
                  "lead": [
                    "create"
                  ],
                  "lead_audit": [
                    "create"
                  ]
                }
              }
            },
            "lead.update_owned": {
              "kind": "record_operation",
              "input": {
                "contact_name": "text",
                "contact_phone": "phone",
                "expected_amount": "currency;precision=18;scale=2;rounding=half_even",
                "source": "select[website:官网|exhibition:展会|referral:转介绍|outbound:外呼]"
              },
              "preconditions": [
                "status not in converted,lost"
              ],
              "handler": {
                "reason": "本人字段更新必须条件写入并与审计原子提交。",
                "access": {
                  "lead": [
                    "get_for_update",
                    "conditional_update"
                  ],
                  "lead_audit": [
                    "create"
                  ]
                }
              }
            },
            "lead.advance": {
              "kind": "record_operation",
              "input": {
                "target_status": "select![contacted|qualified|lost]"
              },
              "preconditions": [
                "status not in converted,lost"
              ],
              "handler": {
                "reason": "负责人状态推进必须校验唯一合法边并原子写入状态与审计。",
                "access": {
                  "lead": [
                    "get_for_update",
                    "conditional_update"
                  ],
                  "lead_audit": [
                    "create"
                  ]
                }
              }
            }
          },
          "state_machines": {
            "lead_lifecycle": {
              "object_key": "lead",
              "field_key": "status",
              "states": [
