{
  "modules": {
    "crm": {
      "features": {
        "crm_followup_reminder": {
          "requirement": {
            "statement": "工作日早晨扫描超过七天未变化的 contacted 线索并向负责人发送每日最多一次的站内提醒。",
            "acceptance": [
              "定时 Scheduler 通过 service run_as Workflow 执行有界扫描。",
              "显式 evaluation_time 仅用于隔离 Runtime 验证，生产缺省使用主机当前时间。",
              "同一线索同一天只产生一条提醒，Runtime 重启后保持。"
            ]
          },
          "objects": {
            "followup_reminder": {
              "fields": {
                "lead": "relation!->lead",
                "recipient": "user!",
                "reminder_date": "date!",
                "dedupe_key": "text!;unique"
              },
              "lifecycle_policy": {
                "mode": "append_only"
              }
            }
          },
          "notification_event_types": {
            "lead.followup_overdue": {
              "source": "project",
              "category": "business",
              "default_severity": "warning",
              "mandatory_in_app": true,
              "template_key": "lead_followup_overdue",
              "default_locale": "zh_CN",
              "locales": {
                "zh_CN": {
                  "title": "线索需要跟进",
                  "body": "线索「{{company_name}}」已超过七天未变化，请及时跟进。",
                  "action_labels": {
                    "open_lead": "查看线索"
                  }
                }
              },
              "variables": {
                "company_name": "text!"
              },
              "actions": {
                "open_lead": {
                  "resource_type": "project_record",
                  "route_key": "my_leads"
                }
              }
            }
          },
          "actions": {
            "lead.scan_stale_contacted": {
              "kind": "bulk_operation",
              "input": {
                "evaluation_time": "datetime"
              },
              "handler": {
                "reason": "逾期线索需有界批量筛选，并批量原子创建每日去重提醒和通知意图。",
                "access": {
                  "lead": [
                    "list"
                  ],
                  "followup_reminder": [
                    "list",
                    "create"
                  ]
                },
                "notification_event_types": [
                  "lead.followup_overdue"
                ]
              }
            }
          },
          "workflows": {
            "stale_lead_followup": {
              "enabled": true,
              "run_as": "crm_workflow_service",
              "trigger": {
                "type": "scheduled"
              },
              "action": {
                "type": "workflow_graph"
              },
              "trigger_contract": {
                "type": "scheduled",
                "object_key": "lead"
              },
              "input_fields": {
                "evaluation_time": "datetime"
              },
              "graph": {
                "nodes": {
                  "scheduled": {
                    "type": "trigger"
                  },
                  "scan": {
                    "type": "action",
                    "contract": {
                      "action": {
                        "action_key": "lead.scan_stale_contacted",
                        "input": {
                          "evaluation_time": "$workflow.evaluation_time"
                        },
                        "on_error": "fail"
                      }
                    }
                  }
                },
                "edges": {
                  "scheduled_scan": {
                    "source": "scheduled",
                    "target": "scan"
                  }
                }
              }
            }
          },
          "scheduled_jobs": {
            "weekday_stale_lead_followup": {
              "status": "enabled",
              "target_type": "workflow",
              "target_key": "stale_lead_followup",
              "schedule": {
                "expression": "0 9 * * 1-5",
                "timezone": "Asia/Shanghai"
              },
              "missed_window_policy": "catch_up_one",
              "max_attempts": 3,
              "timeout_seconds": 300
            }
          }
        }
      }
    }
  }
