    },
    "output": {
      "organization_id": "text!"
    },
    "target_organization": {
      "source": "delivered_organization_unit"
    },
    "handler": {
      "reason": "验收需要通过受控 Action 创建真实部门节点，避免将组织层级降级为业务 Object。",
      "organization_unit_delivery": {
        "operations": [
          "create"
        ],
        "node_types": [
          "department"
        ],
        "parent_source": "workspace_company"
      }
    }
  },
  "sales_person_profile.deliver_identity": {
    "kind": "object_operation",
    "input": {
      "login_id": "email!",
      "display_name": "text!",
      "acceptance_code": "text!;unique",
      "role_key": "select![sales_rep|sales_director]",
      "manager": "user"
    },
    "target_organization": {
      "source": "explicit",
      "input": "target_organization_id"
    },
    "output": {
      "identity_user_id": "text!",
      "initial_credential": "initial_credential"
    },
    "handler": {
      "reason": "验收身份、角色、已解析部门归属、汇报线和业务 Profile 必须原子交付。",
      "organization_unit_delivery": {
        "operations": [
          "resolve"
        ],
        "node_types": [
          "department"
        ]
      },
      "identity_handler_delivery": {
        "operations": [
          "create",
          "resolve"
        ],
        "profile_bindings": {
