          }
        },
        "initial_credential_output_field": "initial_credential"
      }
    }
  }
}
{
  "kind": "record_operation",
  "input": {
    "requested_by": "user!"
  },
  "preconditions": [
    "status == qualified",
    "expected_amount >= 100000"
  ],
  "handler": {
    "reason": "大额 Workflow 在等待前必须幂等记录审批请求和审计。",
    "access": {
      "lead": [
        "get_for_update"
      ],
      "conversion_request": [
        "list",
        "create"
      ],
      "lead_audit": [
        "create"
      ]
    }
  }
}
{
  "enabled": true,
  "run_as": "crm_workflow_service",
  "idempotency_keys": [
    "record_id"
  ],
  "trigger": {
    "type": "manual"
  },
  "action": {
    "type": "workflow_graph"
  },
  "trigger_contract": {
    "type": "manual",
    "object_key": "lead"
  },
  "graph": {
    "nodes": {
      "submitted": {
        "type": "trigger"
      },
      "open_request": {
        "type": "action",
        "contract": {
          "action": {
            "action_key": "lead.open_conversion_approval",
            "input": {
              "requested_by": "$workflow.initiating_user_id"
            },
            "on_error": "fail"
          }
        }
      },
      "director_approval": {
        "type": "approval",
        "contract": {
          "approval": {
            "mode": "any",
            "empty_assignee_policy": "fail",
            "resolvers": [
              {
                "type": "role",
                "role_key": "sales_director"
              }
            ]
          }
        }
      },
      "approve": {
        "type": "action",
        "contract": {
          "action": {
            "action_key": "lead.approve_conversion",
            "on_error": "fail"
          }
        }
      },
      "reject": {
        "type": "action",
        "contract": {
          "action": {
            "action_key": "lead.reject_conversion",
            "input": {
              "rejection_reason": "$workflow.approval_comment"
            },
            "on_error": "fail"
          }
        }
      }
    },
    "edges": {
      "submitted_open": {
        "source": "submitted",
        "target": "open_request"
      },
      "open_approval": {
        "source": "open_request",
        "target": "director_approval"
      },
      "approval_approve": {
        "source": "director_approval",
        "target": "approve",
        "branch": "approved"
      },
      "approval_reject": {
        "source": "director_approval",
        "target": "reject",
        "branch": "rejected"
      }
    }
  }
}
{
  "type": "scheduled"
}

