// OpenConversionApproval implements the project-owned lead.open_conversion_approval Handler.
func OpenConversionApproval(ctx context.Context, caps capabilities.OpenConversionApprovalCapabilities, input capabilities.OpenConversionApprovalInput) (capabilities.OpenConversionApprovalOutput, error) {
	_ = input
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.OpenConversionApprovalOutput{}, err
	}
	below, err := amountBelowConversionThreshold(lead.ExpectedAmount)
	if err != nil {
		return capabilities.OpenConversionApprovalOutput{}, err
	}
	if lead.Status != schema.LeadStatusQualified || below {
		return capabilities.OpenConversionApprovalOutput{}, &capabilities.BusinessError{Code: "lead.open_conversion_approval.precondition_failed", Message: "approval requires a qualified lead of at least 100000.00"}
	}
	existing, err := caps.ConversionRequest.List(ctx, data.NewConversionRequestQuery().
		WhereLeadEqual(schema.NewConversionRequestLeadReference(lead.ID)).WhereStatusEqual(schema.ConversionRequestStatusPending).Page(1, 200))
	if err != nil {
		return capabilities.OpenConversionApprovalOutput{}, err
	}
	if len(existing) != 0 {
		return capabilities.OpenConversionApprovalOutput{}, nil
	}
	if _, err := caps.ConversionRequest.Create(ctx, schema.CreateConversionRequest{
		AmountSnapshot: schema.ConversionRequestAmountSnapshot(lead.ExpectedAmount),
		Lead:           schema.NewConversionRequestLeadReference(lead.ID), RequestedBy: principal.UserID,
		Status: schema.ConversionRequestStatusPending,
	}); err != nil {
		return capabilities.OpenConversionApprovalOutput{}, err
	}
	detail := "large conversion approval requested"
	if _, err := caps.LeadAudit.Create(ctx, schema.CreateLeadAudit{
		Lead: schema.NewLeadAuditLeadReference(lead.ID), Actor: principal.UserID,
		Operation: schema.LeadAuditOperationApprovalRequested, FromStatus: schema.LeadAuditFromStatusQualified,
		ToStatus: schema.LeadAuditToStatusQualified, Detail: &detail, OccurredAt: time.Now().UTC(),
	}); err != nil {
		return capabilities.OpenConversionApprovalOutput{}, err
	}
	return capabilities.OpenConversionApprovalOutput{}, nil
}
