package businessflow

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"testing"
	"time"
)

type crmActors struct {
	Admin, East, EastPeer, North runtimeClient
	EastOrg, NorthOrg            string
	AdminID                      string
}

var crmSetup struct {
	sync.Mutex
	ready bool
	value crmActors
}

func require2xx(t *testing.T, response runtimeResponse, operation string) {
	t.Helper()
	if response.Status/100 != 2 {
		t.Fatalf("%s status=%d body=%s", operation, response.Status, strings.TrimSpace(string(response.Body)))
	}
}

func findString(body []byte, key string) string {
	var value any
	if json.Unmarshal(body, &value) != nil {
		return ""
	}
	var walk func(any) string
	walk = func(current any) string {
		switch typed := current.(type) {
		case map[string]any:
			if found, ok := typed[key].(string); ok && found != "" {
				return found
			}
			for _, nested := range typed {
				if found := walk(nested); found != "" {
					return found
				}
			}
		case []any:
			for _, nested := range typed {
				if found := walk(nested); found != "" {
					return found
				}
			}
		}
		return ""
	}
	return walk(value)
}

func tokenSubject(token string) string {
	parts := strings.Split(token, ".")
	if len(parts) < 2 {
		return ""
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return ""
	}
	var claims map[string]any
	if json.Unmarshal(payload, &claims) != nil {
		return ""
	}
	for _, key := range []string{"sub", "user_id", "principal_id"} {
		if value, ok := claims[key].(string); ok && value != "" {
			return value
		}
	}
	return ""
}

func setupActors(t *testing.T) crmActors {
	t.Helper()
	crmSetup.Lock()
	defer crmSetup.Unlock()
	if crmSetup.ready {
		return crmSetup.value
	}
	admin := workspaceAdminClient(t)
	adminID := tokenSubject(admin.Token)
	provision := func(code, name string, sortOrder int) string {
		invoke := func() (runtimeResponse, error) {
			return admin.runObjectAction(t.Context(), "sales_person_profile", "sales_person_profile.provision_department", map[string]any{
				"code": code, "name": name, "sort_order": sortOrder,
			}, "crm-department-"+code)
		}
		response, err := invoke()
		if err != nil {
			t.Fatal(err)
		}
		if response.Status == http.StatusConflict && strings.Contains(string(response.Body), "auth.authorization_stale") {
			admin = workspaceAdminClient(t)
			response, err = invoke()
			if err != nil {
				t.Fatal(err)
			}
		}
		require2xx(t, response, "provision department")
		organizationID := findString(response.Body, "organization_id")
		if organizationID == "" {
			t.Fatalf("department response has no organization_id: %s", response.Body)
		}
		admin = workspaceAdminClient(t)
		return organizationID
	}
	eastOrg := provision("east", "华东区", 10)
	northOrg := provision("north", "华北区", 20)
	deliver := func(loginID, displayName, code, orgID string) runtimeClient {
		data := map[string]any{"login_id": loginID, "display_name": displayName, "acceptance_code": code, "role_key": "sales_rep"}
		if adminID != "" {
			data["manager"] = adminID
		}
		invoke := func() (runtimeResponse, error) {
			return admin.request(t.Context(), http.MethodPost, "/records/sales_person_profile/actions/sales_person_profile.deliver_identity", map[string]any{
				"data": data, "target_organization_id": orgID,
			}, runtimeRequestOptions{IdempotencyKey: "crm-identity-" + code})
		}
		response, err := invoke()
		if err != nil {
			t.Fatal(err)
		}
		if response.Status == http.StatusConflict && strings.Contains(string(response.Body), "auth.authorization_stale") {
			admin = workspaceAdminClient(t)
			response, err = invoke()
			if err != nil {
				t.Fatal(err)
			}
		}
		require2xx(t, response, "deliver identity")
		initial := findString(response.Body, "initial_password")
		changed := "M1-Crm-" + code + "-Changed!2026"
		client := loginCredential(t, loginID, initial, changed)
		admin = workspaceAdminClient(t)
		return client
	}
	actors := crmActors{
		Admin: admin, EastOrg: eastOrg, NorthOrg: northOrg, AdminID: adminID,
		East:     deliver("east.rep@crm.invalid", "华东销售", "east-rep", eastOrg),
		EastPeer: deliver("east.peer@crm.invalid", "华东销售同事", "east-peer", eastOrg),
		North:    deliver("north.rep@crm.invalid", "华北销售", "north-rep", northOrg),
	}
	crmSetup.value, crmSetup.ready = actors, true
	return actors
}

func createLead(t *testing.T, client runtimeClient, logical, company, amount string) string {
	t.Helper()
	response, err := client.runObjectAction(t.Context(), "lead", "lead.register", map[string]any{
		"company_name": company, "contact_name": company + "联系人", "contact_phone": "13800000000",
		"expected_amount": amount, "source": "website",
	}, "lead-register-"+logical)
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, response, "lead.register")
	leadID := findString(response.Body, "lead_id")
	if leadID == "" {
		t.Fatalf("lead.register response has no lead_id: %s", response.Body)
	}
	return leadID
}

func runLeadAction(t *testing.T, client runtimeClient, leadID, action, logical string, data map[string]any) runtimeResponse {
	t.Helper()
	if !strings.Contains(action, ".") {
		action = "lead." + action
	}
	response, err := client.runRecordAction(t.Context(), "lead", leadID, action, data, logical)
	if err != nil {
		t.Fatal(err)
	}
	return response
}

func qualifyLead(t *testing.T, client runtimeClient, leadID, logical string) {
	t.Helper()
	response := runLeadAction(t, client, leadID, "advance", logical+"-contacted", map[string]any{"target_status": "contacted"})
	require2xx(t, response, "lead.advance contacted")
	response = runLeadAction(t, client, leadID, "advance", logical+"-qualified", map[string]any{"target_status": "qualified"})
	require2xx(t, response, "lead.advance qualified")
}

func getRecord(t *testing.T, client runtimeClient, objectKey, recordID string) recordEnvelope {
	t.Helper()
	response, err := client.request(t.Context(), http.MethodGet, "/records/"+url.PathEscape(objectKey)+"/items/"+url.PathEscape(recordID), nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, response, "record detail")
	var record recordEnvelope
	if err := json.Unmarshal(response.Body, &record); err != nil {
		t.Fatal(err)
	}
	return record
}

func findRecordByCompany(t *testing.T, client runtimeClient, objectKey, company string) (recordEnvelope, bool) {
	t.Helper()
	page, err := client.listRecords(t.Context(), objectKey, 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	for _, item := range page.Items {
		if item.Data["company_name"] == company {
			return item, true
		}
	}
	return recordEnvelope{}, false
}

func relationID(value any) string {
	if direct, ok := value.(string); ok {
		return direct
	}
	if object, ok := value.(map[string]any); ok {
		for _, key := range []string{"id", "record_id", "value"} {
			if result, ok := object[key].(string); ok {
				return result
			}
		}
	}
	return ""
}

func countCustomersForLead(t *testing.T, client runtimeClient, leadID string) int {
	t.Helper()
	page, err := client.listRecords(t.Context(), "customer", 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	count := 0
	for _, item := range page.Items {
		if relationID(item.Data["source_lead"]) == leadID {
			count++
		}
	}
	return count
}

func runWorkflow(t *testing.T, client runtimeClient, workflowKey, leadID, logical string, input map[string]any) runtimeResponse {
	t.Helper()
	body := map[string]any{"object_key": "lead", "record_id": leadID, "input": input}
	response, err := client.request(t.Context(), http.MethodPost, "/workflow/definitions/"+url.PathEscape(workflowKey)+"/run", body, runtimeRequestOptions{IdempotencyKey: logical})
	if err != nil {
		t.Fatal(err)
	}
	return response
}

func waitForTask(t *testing.T, client runtimeClient, processID string) workflowTask {
	t.Helper()
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		response, err := client.request(t.Context(), http.MethodGet, "/workflow/tasks?status=pending&limit=100", nil, runtimeRequestOptions{})
		if err != nil {
			t.Fatal(err)
		}
		if response.Status/100 == 2 {
			tasks, err := decodeWorkflowTasks(response.Body)
			if err != nil {
				t.Fatal(err)
			}
			for _, task := range tasks {
				if processID == "" || task.ProcessID == processID {
					return task
				}
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("pending workflow task not found for process %q", processID)
	return workflowTask{}
}

func decodeJSONMap(t *testing.T, body []byte) map[string]any {
	t.Helper()
	var result map[string]any
	if err := json.Unmarshal(body, &result); err != nil {
		t.Fatalf("decode JSON: %v body=%s", err, body)
	}
	return result
}

func uniqueForPhase(flow string) string {
	return strings.ToLower(flow) + "-stable"
}

func statusValue(record recordEnvelope) string { return fmt.Sprint(record.Data["status"]) }
package businessflow

import (
	"net/http"
	"strings"
	"testing"
	"time"
)

func TestBF03ApprovalAcceptedTransactionAndNotification(t *testing.T) {
	phase := managedPhase(t)
	actors := setupActors(t)
	logical := uniqueForPhase("BF03")
	leadID := createLead(t, actors.East, logical, "BF03大额批准", "150000.00")
	qualifyLead(t, actors.East, leadID, logical)
	run := runWorkflow(t, actors.East, "large_lead_conversion", leadID, logical+"-workflow", map[string]any{})
	require2xx(t, run, "large conversion workflow")
	processID := findString(run.Body, "process_id")
	if phase == "initial" {
		task := waitForTask(t, actors.Admin, processID)
		denied, err := actors.East.request(t.Context(), http.MethodPost, "/workflow/tasks/"+task.ID+"/approve", map[string]any{"comment": "越权"}, runtimeRequestOptions{IdempotencyKey: logical + "-unauthorized"})
		if err != nil {
			t.Fatal(err)
		}
		if denied.Status != http.StatusForbidden {
			t.Fatalf("rep approval status=%d body=%s", denied.Status, denied.Body)
		}
		if statusValue(getRecord(t, actors.East, "lead", leadID)) != "qualified" || countCustomersForLead(t, actors.Admin, leadID) != 0 {
			t.Fatal("unauthorized approval changed business state")
		}
		approved, err := actors.Admin.request(t.Context(), http.MethodPost, "/workflow/tasks/"+task.ID+"/approve", map[string]any{"comment": "批准"}, runtimeRequestOptions{IdempotencyKey: logical + "-approve"})
		if err != nil {
			t.Fatal(err)
		}
		require2xx(t, approved, "director approval")
	}
	deadline := time.Now().Add(15 * time.Second)
	for statusValue(getRecord(t, actors.Admin, "lead", leadID)) != "converted" && time.Now().Before(deadline) {
		time.Sleep(100 * time.Millisecond)
	}
	lead := getRecord(t, actors.Admin, "lead", leadID)
	if statusValue(lead) != "converted" || countCustomersForLead(t, actors.Admin, leadID) != 1 {
		t.Fatalf("approved conversion not atomic: status=%s customers=%d", statusValue(lead), countCustomersForLead(t, actors.Admin, leadID))
	}
	inbox, err := actors.East.request(t.Context(), http.MethodGet, "/notification/inbox?limit=100", nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, inbox, "approval notification inbox")
	if !strings.Contains(string(inbox.Body), "lead.conversion_approved") {
		t.Fatalf("approval notification missing: %s", inbox.Body)
	}
	emitEvidence(t, phase, "BF03", passedStep("approval", "workflow.approval.accepted", "runtime.workflow", []string{"6", "7", "8", "9", "13"}, map[string]any{
