func TestBF04ApprovalRejectedReasonNotificationAndNoCustomer(t *testing.T) {
	phase := managedPhase(t)
	actors := setupActors(t)
	logical := uniqueForPhase("BF04")
	leadID := createLead(t, actors.East, logical, "BF04大额拒绝", "200000.00")
	qualifyLead(t, actors.East, leadID, logical)
	run := runWorkflow(t, actors.East, "large_lead_conversion", leadID, logical+"-workflow", map[string]any{})
	require2xx(t, run, "rejection workflow")
	processID := findString(run.Body, "process_id")
	reason := "客户信用资料不足"
	if phase == "initial" {
		task := waitForTask(t, actors.Admin, processID)
		beforeDenied := getRecord(t, actors.Admin, "lead", leadID)
		denied, err := actors.East.request(t.Context(), http.MethodPost, "/workflow/tasks/"+task.ID+"/reject", map[string]any{"comment": "越权拒绝"}, runtimeRequestOptions{IdempotencyKey: logical + "-unauthorized"})
		if err != nil {
			t.Fatal(err)
		}
		if denied.Status != http.StatusForbidden {
			t.Fatalf("rep rejection status=%d body=%s", denied.Status, denied.Body)
		}
		afterDenied := getRecord(t, actors.Admin, "lead", leadID)
		if afterDenied.UpdatedAt != beforeDenied.UpdatedAt || statusValue(afterDenied) != "qualified" || countCustomersForLead(t, actors.Admin, leadID) != 0 {
			t.Fatal("unauthorized rejection changed durable business state")
		}
		rejected, err := actors.Admin.request(t.Context(), http.MethodPost, "/workflow/tasks/"+task.ID+"/reject", map[string]any{"comment": reason}, runtimeRequestOptions{IdempotencyKey: logical + "-reject"})
		if err != nil {
			t.Fatal(err)
		}
		require2xx(t, rejected, "director rejection")
	}
	time.Sleep(100 * time.Millisecond)
	lead := getRecord(t, actors.Admin, "lead", leadID)
	if statusValue(lead) != "qualified" || countCustomersForLead(t, actors.Admin, leadID) != 0 {
		t.Fatalf("rejection terminal state invalid: status=%s customers=%d", statusValue(lead), countCustomersForLead(t, actors.Admin, leadID))
	}
	requests, err := actors.Admin.listRecords(t.Context(), "conversion_request", 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	foundReason := false
	for _, item := range requests.Items {
		if relationID(item.Data["lead"]) == leadID && item.Data["status"] == "rejected" && item.Data["rejection_reason"] == reason {
			foundReason = true
		}
	}
	if !foundReason {
		t.Fatal("durable rejection reason not found")
	}
	inbox, err := actors.East.request(t.Context(), http.MethodGet, "/notification/inbox?limit=100", nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, inbox, "rejection notification inbox")
	if !strings.Contains(string(inbox.Body), "lead.conversion_rejected") || !strings.Contains(string(inbox.Body), reason) {
		t.Fatalf("rejection notification missing: %s", inbox.Body)
	}
	emitEvidence(t, phase, "BF04", passedStep("rejection", "workflow.approval.rejected", "runtime.workflow", []string{"6", "7", "8", "9", "13"}, map[string]any{
		"process_id": processID, "unauthorized_denied": true, "unauthorized_state_unchanged": true, "lead_status": "qualified", "rejection_reason": reason, "customer_count": 0, "notification_readable": true,
	}))
}
