func TestBF06WeekdayOverdueReminderDedupAndRestart(t *testing.T) {
	phase := managedPhase(t)
	actors := setupActors(t)
	logical := uniqueForPhase("BF06")
	leadID := createLead(t, actors.East, logical, "BF06逾期跟进", "30000.00")
	contacted := runLeadAction(t, actors.East, leadID, "advance", logical+"-contacted", map[string]any{"target_status": "contacted"})
	require2xx(t, contacted, "contact lead")
	evaluation := time.Date(2030, time.September, 9, 1, 0, 0, 0, time.UTC)
	run := runWorkflow(t, actors.Admin, "stale_lead_followup", leadID, logical+"-scan", map[string]any{"evaluation_time": evaluation.Format(time.RFC3339)})
	require2xx(t, run, "stale lead workflow")
	deadline := time.Now().Add(15 * time.Second)
	reminderCount := 0
	for time.Now().Before(deadline) {
		page, err := actors.Admin.listRecords(t.Context(), "followup_reminder", 1, 200)
		if err != nil {
			t.Fatal(err)
		}
		reminderCount = 0
		for _, item := range page.Items {
			if relationID(item.Data["lead"]) == leadID {
				reminderCount++
			}
		}
		if reminderCount == 1 {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}
	if reminderCount != 1 {
		t.Fatalf("expected one reminder, got %d", reminderCount)
	}
	replayed := runWorkflow(t, actors.Admin, "stale_lead_followup", leadID, logical+"-scan", map[string]any{"evaluation_time": evaluation.Format(time.RFC3339)})
	require2xx(t, replayed, "stale workflow replay")
	page, err := actors.Admin.listRecords(t.Context(), "followup_reminder", 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	reminderCount = 0
	for _, item := range page.Items {
		if relationID(item.Data["lead"]) == leadID {
			reminderCount++
		}
	}
	if reminderCount != 1 {
		t.Fatalf("daily reminder dedupe failed, count=%d", reminderCount)
	}
	inbox, err := actors.East.request(t.Context(), http.MethodGet, "/notification/inbox?limit=100", nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, inbox, "followup inbox")
	if !strings.Contains(string(inbox.Body), "lead.followup_overdue") {
		t.Fatalf("followup notification missing: %s", inbox.Body)
	}
	emitEvidence(t, phase, "BF06", passedStep("reminder", "scheduler.weekday_overdue_reminder", "runtime.scheduler", []string{"14"}, map[string]any{
		"lead_id": leadID, "weekday": true, "older_than_seven_days": true, "reminder_count": 1, "same_day_replay_deduped": true, "restart_durable": phase == "restart", "notification_readable": true,
	}))
}
