func TestBF08GovernedCSVExportAuditOwnershipAndDownload(t *testing.T) {
	phase := managedPhase(t)
	actors := setupActors(t)
	createLead(t, actors.East, uniqueForPhase("BF08"), "BF08导出线索", "76543.21")
	query, err := actors.Admin.request(t.Context(), http.MethodPost, "/report/lead_detail/query", map[string]any{"parameters": map[string]any{}, "page_size": 200}, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, query, "lead detail report")
	var queried struct {
		RowCount int `json:"row_count"`
	}
	if err := json.Unmarshal(query.Body, &queried); err != nil {
		t.Fatal(err)
	}
	logical := uniqueForPhase("BF08")
	scope := map[string]any{
		"purpose":          "M1 CRM acceptance export",
		"freshness":        map[string]any{"mode": "realtime"},
		"field_projection": []string{"company_name", "contact_name", "contact_phone", "expected_amount", "source", "status"},
	}
	scopePayload, err := json.Marshal(scope)
	if err != nil {
		t.Fatal(err)
	}
	scopeDigest := sha256.Sum256(scopePayload)
	auditCreated, err := actors.Admin.request(t.Context(), http.MethodPost, "/records/lead_report_export_audit", map[string]any{"data": map[string]any{
		"report_key": "lead_detail", "requested_by": actors.AdminID, "status": "requested",
		"row_count": queried.RowCount, "scope_hash": hex.EncodeToString(scopeDigest[:]),
	}}, runtimeRequestOptions{IdempotencyKey: logical + "-audit"})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, auditCreated, "create governed export audit")
	auditID := findString(auditCreated.Body, "id")
	if auditID == "" {
		t.Fatalf("created export audit has no id: %s", auditCreated.Body)
	}
	prepareBody := map[string]any{"audit_id": auditID, "scope": scope}
	prepared, err := actors.Admin.request(t.Context(), http.MethodPost, "/report/lead_detail/exports/lead_detail_export/prepare", prepareBody, runtimeRequestOptions{
		IdempotencyKey: "report.exports.prepare:" + logical, OperationConfirmation: "confirmed", OperationReason: "M1 CRM acceptance export",
	})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, prepared, "prepare governed export")
	jobID := findString(prepared.Body, "job_id")
	if jobID == "" {
		jobID = findString(prepared.Body, "id")
	}
	if jobID == "" {
		t.Fatalf("prepared export has no job_id: %s", prepared.Body)
	}
	deniedPrepare, err := actors.East.request(t.Context(), http.MethodPost, "/report/lead_detail/exports/lead_detail_export/prepare", prepareBody, runtimeRequestOptions{
		IdempotencyKey: "report.exports.prepare:" + logical + "-denied", OperationConfirmation: "confirmed", OperationReason: "unauthorized sales attempt",
	})
	if err != nil {
		t.Fatal(err)
	}
	if deniedPrepare.Status != http.StatusForbidden {
		t.Fatalf("sales export prepare status=%d body=%s", deniedPrepare.Status, deniedPrepare.Body)
	}
	provider := findString(prepared.Body, "provider")
	jobPath := "/data-exchange/jobs/" + url.PathEscape(jobID)
	if provider != "" {
		jobPath += "?provider=" + url.QueryEscape(provider) + "&operation=export"
	}
	foreignJob, err := actors.East.request(t.Context(), http.MethodGet, jobPath, nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	if foreignJob.Status != http.StatusForbidden && foreignJob.Status != http.StatusNotFound {
		t.Fatalf("foreign job detail status=%d", foreignJob.Status)
	}
	jobStatus := ""
	deadline := time.Now().Add(20 * time.Second)
	for time.Now().Before(deadline) {
		job, err := actors.Admin.request(t.Context(), http.MethodGet, jobPath, nil, runtimeRequestOptions{})
		if err != nil {
			t.Fatal(err)
		}
		if job.Status/100 == 2 {
			jobStatus = findString(job.Body, "status")
			if jobStatus == "completed" {
				break
			}
			if jobStatus == "failed" {
				t.Fatalf("export job failed: %s", job.Body)
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	if jobStatus != "completed" {
		t.Fatalf("export job did not complete: status=%q", jobStatus)
	}
	downloadPath := "/data-exchange/jobs/" + url.PathEscape(jobID) + "/download"
	if provider != "" {
		downloadPath += "?provider=" + url.QueryEscape(provider) + "&operation=export"
	}
	download, err := actors.Admin.request(t.Context(), http.MethodGet, downloadPath, nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, download, "download governed export")
	contentType := download.Header.Get("Content-Type")
	if len(download.Body) == 0 || !strings.Contains(strings.ToLower(contentType), "csv") {
		t.Fatalf("invalid export artifact content_type=%q bytes=%d", contentType, len(download.Body))
	}
	rows, err := csv.NewReader(bytes.NewReader(download.Body)).ReadAll()
	if err != nil {
		t.Fatalf("parse CSV: %v", err)
	}
	if len(rows) == 0 || len(rows)-1 != queried.RowCount {
		t.Fatalf("CSV row count=%d report row count=%d", len(rows)-1, queried.RowCount)
	}
	digest := sha256.Sum256(download.Body)
	digestHex := hex.EncodeToString(digest[:])
	foreign, err := actors.East.request(t.Context(), http.MethodGet, downloadPath, nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	if foreign.Status != http.StatusForbidden && foreign.Status != http.StatusNotFound {
		t.Fatalf("foreign download status=%d", foreign.Status)
	}
	audits, err := actors.Admin.listRecords(t.Context(), "lead_report_export_audit", 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	if len(audits.Items) == 0 {
		t.Fatal("export audit record missing")
	}
	emitEvidence(t, phase, "BF08",
		passedStep("query", "report.query", "runtime.report", []string{"16"}, map[string]any{"row_count": queried.RowCount}),
		passedStep("prepare", "report.prepare", "runtime.report", []string{"16"}, map[string]any{"accepted": true, "job_id": jobID}),
		passedStep("prepare-denied", "report.prepare.unauthorized_denied", "runtime.report", []string{"16"}, map[string]any{"access_denied": true, "different_actor": true, "job_id": jobID}),
		passedStep("owner", "data_exchange.job.owner_bound", "runtime.data_exchange", []string{"16"}, map[string]any{"requester_owned": true, "foreign_job_hidden": true, "job_id": jobID}),
		passedStep("completed", "data_exchange.job.completed", "runtime.data_exchange", []string{"16"}, map[string]any{"job_id": jobID, "job_status": "completed"}),
		passedStep("download", "data_exchange.job.download", "runtime.data_exchange", []string{"16"}, map[string]any{"job_id": jobID, "actual_job_download": true, "byte_count": len(download.Body), "content_type": contentType}),
		passedStep("foreign-denied", "data_exchange.job.foreign_download_denied", "runtime.data_exchange", []string{"16"}, map[string]any{"access_denied": true, "different_actor": true, "job_id": jobID}),
		passedStep("csv", "artifact.csv.content_validated", "runtime.data_exchange", []string{"16"}, map[string]any{"csv_parsed": true, "row_count_matches_report": true, "content_hash_verified": digestHex != ""}),
		passedStep("audit", "export.audit.readback", "runtime.records", []string{"16"}, map[string]any{"audit_record_count": len(audits.Items)}),
	)
}

